```dart
import 'package:collection/collection.dart';

class Transaction {
  final String coinName;
  final DateTime datetime;
  final double profitEarnedOrLoss;

  const Transaction({required this.coinName, required this.datetime, required this.profitEarnedOrLoss});
}

List<Transaction> transactions = [
  // Sample transactions
];

void main() {
  List<String> topThreeCoinsWithHighestAverageProfit = findTopCoins(transactions, (t) => t.profitEarnedOrLoss);
  List<String> topThreeCoinsWithHighestAverageLoss = findTopCoins(transactions, (t) => -t.profitEarnedOrLoss);

  print('Top 3 Coins with Highest Average Profit: $topThreeCoinsWithHighestAverageProfit');
  print('Top 3 Coins with Highest Average Loss: $topThreeCoinsWithHighestAverageLoss');
}

List<String> findTopCoins(List<Transaction> transactions, Function(Transaction) keyExtractor) {
  var groupedTransactions = transactions.groupBy((t) => keyExtractor(t));

  var sortedGroupedTransactions = groupedTransactions.entries
      .map((e) => MapEntry(e.key, e.value.reduce((a, b) => a + b)))
      .toList();

  sortedGroupedTransactions.sort((a, b) => b.value.compareTo(a.value));

  return sortedGroupedTransactions.sublist(0, 3).map((e) => e.key).toList();
}
```

