```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <input>\n", argv[0]);
        return 1;
    }

    char *input = argv[1];
    size_t input_length = strlen(input);

    // Allocate memory for the C string
    char *cstring = malloc(input_length + 1);

    // Copy the input to the C string
    strcpy(cstring, input);

    // Add a null terminator to the C string
    cstring[input_length] = '\0';

    printf("C string: %s\n", cstring);

    // Free the memory allocated for the C string
    free(cstring);

    return 0;
}
