To create a simple toast notification using React Context, follow these steps:

1. First, let's create a `NotificationContext` file to manage the notification state and provide it as a context to our components.

```javascript
import React, { createContext, useReducer } from 'react';

const initialState = {
  isOpen: false,
  message: '',
};

function notificationReducer(state, action) {
  switch (action.type) {
    case 'OPEN_NOTIFICATION':
      return { ...state, isOpen: true, message: action.message };
    case 'CLOSE_NOTIFICATION':
      return { ...state, isOpen: false, message: '' };
    default:
      return state;
  }
}

export const NotificationContext = createContext();

function NotificationProvider({ children }) {
  const [state, dispatch] = useReducer(notificationReducer, initialState);

  function openNotification(message) {
    dispatch({ type: 'OPEN_NOTIFICATION', message });
  }

  function closeNotification() {
    dispatch({ type: 'CLOSE_NOTIFICATION' });
  }

  return (
    <NotificationContext.Provider value={{ state, openNotification, closeNotification }}>
      {children}
    </NotificationContext.Provider>
  );
}

export default NotificationProvider;
```

2. Now, let's create a `ToastNotification` component that will display the toast notification.

```javascript
import React from 'react';
import { NotificationContext } from './NotificationContext';

function ToastNotification() {
  const { isOpen, message } = React.useContext(NotificationContext);

  if (!isOpen) {
    return null;
  }

  return (
    <div className="toast">
      {message}
      <button onClick={() => NotificationContext.openNotification('')}>Close</button>
    </div>
  );
}

export default ToastNotification;
```

3. Finally, let's use the `NotificationProvider` in our main application component to provide the notification context to our components.

