To achieve this, you'll need to use PowerShell along with the ActiveDirectory module. Here's a script that will recursively check folders for ACLs referring to SIDs in the SIDHistory of any user or group in the domain:

```powershell
# Import ActiveDirectory module
Import-Module ActiveDirectory

# Define function to check ACLs for SIDs in SIDHistory
Function CheckSIDHistoryAcl {
    Param(
        [Parameter(Mandatory=$true)]
        $Path
    )

    # Get ACLs for the folder
    $acl = (Get-Acl -Path $Path).Access

    # Loop through each access rule
    foreach ($rule in $acl) {
        # Check if the rule refers to a SID in the SIDHistory
        if ($rule.IdentityReference -match '^S-1-5-21-(.\*)') {
            # Get the SID and its corresponding domain name
            $sid = $rule.IdentityReference
            $domain = (Get-ADUser -Filter "SamAccountName -eq '$sid'" -Properties Domain).Domain

            # Check if the SID is in the SIDHistory of any user or group in the domain
            if ((Get-ADUser -Filter "SIDHistory -eq '$sid'" -Properties SamAccountName, Domain).Count -gt 0) {
                # Output the folder path and the SID
                Write-Host "Folder path: $Path"
                Write-Host "SID: $sid"
                Write-Host "Domain: $domain"
            }
        }
    }
}

# Define function to recursively check folders
Function RecursiveCheck {
    Param(
        [Parameter(Mandatory=$true)]
        $Path
    )

    # Check the current folder
    CheckSIDHistoryAcl -Path $Path

    # Recursively check subfolders
    Get-ChildItem -Path $Path -Directory | ForEach-Object {
        RecursiveCheck -Path $_.FullName
    }
}

# Start the recursive check
RecursiveCheck -Path "C:\Path\To\Your\Root\Folder"
